solutionCode:
fun clampPower(power: Double): Double {
    if (power > 1.0) return 1.0
    if (power < -1.0) return -1.0
    return power
}

testCode:
import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testNormalValue() {
        Assert.assertEquals(0.5, clampPower(0.5), 0.001)
    }

    @Test
    fun testTooHigh() {
        Assert.assertEquals(1.0, clampPower(1.5), 0.001)
    }

    @Test
    fun testTooLow() {
        Assert.assertEquals(-1.0, clampPower(-2.0), 0.001)
    }

    @Test
    fun testBoundary() {
        Assert.assertEquals(1.0, clampPower(1.0), 0.001)
    }
}
